  ('Okemo', 'VT', 'US', 43.401, -72.717, 'skied'),
  ('Ascutney', 'VT', 'US', 43.432, -72.45, 'skied'),
  ('Sugarloaf', 'ME', 'US', 45.031, -70.313, 'skied'),
  ('Sunday River', 'ME', 'US', 44.473, -70.857, 'skied'),
  ('Butternut', 'MA', 'US', 42.183, -73.322, 'skied'),
  ('Elk Mountain', 'PA', 'US', 41.722, -75.557, 'skied'),
  ('Montage', 'PA', 'US', 41.356, -75.659, 'skied'),
  ('Blue Mountain', 'PA', 'US', 40.811, -75.513, 'skied'),
