  ('Big Sky', 'MT', 'US', 45.284, -111.401, 'skied'),
  ('Jackson Hole', 'WY', 'US', 43.588, -110.828, 'skied'),
  ('Powder Mountain', 'UT', 'US', 41.379, -111.781, 'skied'),
