  ('Steamboat', 'CO', 'US', 40.457, -106.804, 'skied'),
  ('Winter Park', 'CO', 'US', 39.887, -105.763, 'skied'),
  ('Vail', 'CO', 'US', 39.606, -106.355, 'skied'),
  ('Telluride', 'CO', 'US', 37.937, -107.846, 'skied'),
  ('Arizona Snowbowl', 'AZ', 'US', 35.331, -111.711, 'skied'),
