  ('Killington', 'VT', 'US', 43.62, -72.797, 'planned')
) as v(name, region, country, lat, lon, status)
where not exists (select 1 from public.ski_mountains m where m.name = v.name);

insert into public.ski_trips (mountain_id, year)
select m.id, null
from (values
  ('Tremblant', 3),
  ('Whiteface', 1),
  ('Gore', 1),
  ('West Mountain', 1),
  ('Hunter', 1),
  ('Okemo', 1),
  ('Ascutney', 1),
  ('Sugarloaf', 1),
  ('Sunday River', 1),
  ('Butternut', 1),
  ('Elk Mountain', 1),
  ('Montage', 1),
  ('Blue Mountain', 1),
  ('Whistler Blackcomb', 1),
  ('Big Sky', 1),
  ('Jackson Hole', 1),
  ('Powder Mountain', 1),
  ('Snowbasin', 1),
  ('Park City', 1),
  ('Alta', 1),
  ('Snowbird', 1),
  ('Steamboat', 1),
  ('Winter Park', 1),
  ('Vail', 1),
  ('Telluride', 1),
  ('Arizona Snowbowl', 1)
) as v(name, trips)
join public.ski_mountains m on m.name = v.name
cross join generate_series(1, v.trips)
where not exists (select 1 from public.ski_trips t where t.mountain_id = m.id);

commit;
